#include <vector>
#include <unordered_map>
using namespace std;

class Solution {
public:
    bool canFormArray(vector<int>& arr, vector<vector<int>>& pieces) {
        unordered_map<int, int> piece_idx;
        for (int i = 0; i < (int)pieces.size(); ++i) {
            piece_idx[pieces[i][0]] = i;
        }
        int i = 0, n = arr.size();
        while (i < n) {
            if (piece_idx.find(arr[i]) == piece_idx.end()) return false;
            const auto& piece = pieces[piece_idx[arr[i]]];
            for (int x : piece) {
                if (i >= n || arr[i] != x) return false;
                i++;
            }
        }
        return true;
    }
};

import java.util.*;

class Solution {
    public boolean canFormArray(int[] arr, int[][] pieces) {
        Map<Integer, int[]> pieceMap = new HashMap<>();
        for (int[] p : pieces) {
            pieceMap.put(p[0], p);
        }
        int i = 0, n = arr.length;
        while (i < n) {
            if (!pieceMap.containsKey(arr[i])) return false;
            int[] piece = pieceMap.get(arr[i]);
            for (int x : piece) {
                if (i >= n || arr[i] != x) return false;
                i++;
            }
        }
        return true;
    }
}

/**
 * @param {number[]} arr
 * @param {number[][]} pieces
 * @return {boolean}
 */
var canFormArray = function(arr, pieces) {
    const pieceMap = new Map();
    for (const p of pieces) {
        pieceMap.set(p[0], p);
    }
    let i = 0;
    const n = arr.length;
    while (i < n) {
        if (!pieceMap.has(arr[i])) return false;
        const piece = pieceMap.get(arr[i]);
        for (const x of piece) {
            if (i >= n || arr[i] !== x) return false;
            i++;
        }
    }
    return true;
};
